cd /tmp && python3 << 'EOF'
unit = "(((((((....))(((((((((...))))..((((...)))))))))((....)))))))"
n = len(unit)
seq = [None]*n
stack=[]
pairs={}
for i,c in enumerate(unit):
    if c=='(':
        stack.append(i)
    elif c==')':
        j=stack.pop()
        pairs[j]=i
        pairs[i]=j

# assign pair GC alternating strong, unpaired loops with GAAA/GAA motifs
comp = {'G':'C','C':'G','A':'U','U':'A'}

done=set()
gc_cycle = ['G','C']
idx=0
for i in range(n):
    if i in done: continue
    if i in pairs and pairs[i]>i:
        j = pairs[i]
        b = gc_cycle[idx%2]
        idx+=1
        seq[i]=b
        seq[j]=comp[b]
        done.add(i); done.add(j)

# now unpaired runs -> find runs of None that are unpaired (loops/linkers)
i=0
while i<n:
    if seq[i] is None:
        j=i
        while j<n and seq[j] is None:
            j+=1
        length=j-i
        if length==4:
            fill=['G','A','A','A']
        elif length==3:
            fill=['G','A','A']
        elif length==2:
            fill=['A','A']
        else:
            fill=['A']*length
        for k in range(length):
            seq[i+k]=fill[k]
        i=j
    else:
        i+=1

seq = ''.join(seq)
print(seq, len(seq))
